mapper.select:
/* egovframework.smartcity.mapper.ComplaintMapper.selectComplaintList */ SELECT COMPLAINT_ID AS complaintId, TITLE AS title, CATEGORY AS category, CONTENT AS content, PETITIONER_NAME AS petitionerName, PETITIONER_TEL AS petitionerTel, OCCUR_ADDRESS AS occurAddress, DISTRICT AS district, RELATED_FAC_ID AS relatedFacId, TO_CHAR(REG_DATE, 'YYYY-MM-DD HH24:MI') AS regDate, STATUS AS status, ASSIGNED_DEPT AS assignedDept, HANDLER_NAME AS handlerName, TO_CHAR(RESOLVE_DATE, 'YYYY-MM-DD HH24:MI') AS resolveDate, RESOLVE_COMMENT AS resolveComment, SATISFACTION AS satisfaction FROM TB_CIVIL_COMPLAINT
AND DISTRICT = #{district}
AND STATUS = #{status}
AND (COMPLAINT_ID LIKE '%' || #{keyword} || '%' OR TITLE LIKE '%' || #{keyword} || '%' OR CONTENT LIKE '%' || #{keyword} || '%' OR PETITIONER_NAME LIKE '%' || #{keyword} || '%')
ORDER BY REG_DATE DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY

/* egovframework.smartcity.mapper.ComplaintMapper.selectComplaintCount */
SELECT COUNT(1)
FROM TB_CIVIL_COMPLAINT


        AND DISTRICT = #{district}


        AND STATUS = #{status}


        AND (COMPLAINT_ID LIKE '%' || #{keyword} || '%' OR TITLE LIKE '%' || #{keyword} || '%' OR CONTENT LIKE '%' || #{keyword} || '%' OR PETITIONER_NAME LIKE '%' || #{keyword} || '%')
